//! Real-kernel metadata check of the retained shutdown errno helper.
const IHK_SMP_SHUTDOWN_V6_POST_EFFECT: i64 = 1_i64 << 62;

fn shutdown_v6_post_effect(error: kernel::error::Error) -> i64 {
    IHK_SMP_SHUTDOWN_V6_POST_EFFECT | (error.to_errno() as u32 as i64)
}

/// Keep the exact private helper reachable during this metadata-only check.
pub fn check_shutdown_error(error: kernel::error::Error) -> i64 {
    shutdown_v6_post_effect(error)
}
